/// Frame duration
enum lc3_dt {
  LC3_DT_2M5(0),
  LC3_DT_5M(1),
  LC3_DT_7M5(2),
  LC3_DT_10M(3),
  LC3_NUM_DT(4);

  final int value;
  const lc3_dt(this.value);

  static lc3_dt fromValue(int value) => switch (value) {
    0 => LC3_DT_2M5,
    1 => LC3_DT_5M,
    2 => LC3_DT_7M5,
    3 => LC3_DT_10M,
    4 => LC3_NUM_DT,
    _ => throw ArgumentError("Unknown value for lc3_dt: $value"),
  };
}

/// Sampling frequency and high-resolution mode
enum lc3_srate {
  LC3_SRATE_8K(0),
  LC3_SRATE_16K(1),
  LC3_SRATE_24K(2),
  LC3_SRATE_32K(3),
  LC3_SRATE_48K(4),
  LC3_SRATE_48K_HR(5),
  LC3_SRATE_96K_HR(6),
  LC3_NUM_SRATE(7);

  final int value;
  const lc3_srate(this.value);

  static lc3_srate fromValue(int value) => switch (value) {
    0 => LC3_SRATE_8K,
    1 => LC3_SRATE_16K,
    2 => LC3_SRATE_24K,
    3 => LC3_SRATE_32K,
    4 => LC3_SRATE_48K,
    5 => LC3_SRATE_48K_HR,
    6 => LC3_SRATE_96K_HR,
    7 => LC3_NUM_SRATE,
    _ => throw ArgumentError("Unknown value for lc3_srate: $value"),
  };
}

