/// Callback functions for accessing the stream.
final class OpusEncCallbacks extends ffi.Struct {
  /// Callback for writing to the stream.
  external ope_write_func write;

  /// Callback for closing the stream.
  external ope_close_func close;
}

/// Called for writing a page.
/// \param user_data user-defined data passed to the callback
/// \param ptr       buffer to be written
/// \param len       number of bytes to be written
/// \return          error code
/// \retval 0        success
/// \retval 1        failure
typedef ope_write_func = ffi.Pointer<ffi.NativeFunction<ope_write_funcFunction>>;
typedef ope_write_funcFunction =
    ffi.Int Function(ffi.Pointer<ffi.Void> user_data, ffi.Pointer<ffi.UnsignedChar> ptr, opus_int32 len);
typedef Dartope_write_funcFunction =
    int Function(ffi.Pointer<ffi.Void> user_data, ffi.Pointer<ffi.UnsignedChar> ptr, Dartopus_int32 len);

/// Called for closing a stream.
/// \param user_data user-defined data passed to the callback
/// \return          error code
/// \retval 0        success
/// \retval 1        failure
typedef ope_close_func = ffi.Pointer<ffi.NativeFunction<ope_close_funcFunction>>;
typedef ope_close_funcFunction = ffi.Int Function(ffi.Pointer<ffi.Void> user_data);
typedef Dartope_close_funcFunction = int Function(ffi.Pointer<ffi.Void> user_data);

